import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:flutter/material.dart';class ChatScreen extends StatefulWidget{final String sellerId,sellerName,productId,productTitle;const ChatScreen({super.key,required this.sellerId,required this.sellerName,required this.productId,required this.productTitle});@override State<ChatScreen> createState()=>_C();}class _C extends State<ChatScreen>{final text=TextEditingController();String get uid=>FirebaseAuth.instance.currentUser!.uid;String get chatId=>[uid,widget.sellerId]..sort().join('_');Future<void> send()async{final v=text.text.trim();if(v.isEmpty)return;await FirebaseFirestore.instance.collection('chats').doc(chatId).set({'participants':[uid,widget.sellerId],'productId':widget.productId,'productTitle':widget.productTitle,'updatedAt':FieldValue.serverTimestamp()});await FirebaseFirestore.instance.collection('chats').doc(chatId).collection('messages').add({'senderId':uid,'text':v,'createdAt':FieldValue.serverTimestamp()});text.clear();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.sellerName)),body:Column(children:[Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('chats').doc(chatId).collection('messages').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(reverse:true,children:s.data!.docs.map((d){final x=d.data();return Padding(padding:const EdgeInsets.all(8),child:Align(alignment:x['senderId']==uid?Alignment.centerRight:Alignment.centerLeft,child:Text(x['text']??'')));}).toList());})),Row(children:[Expanded(child:TextField(controller:text,decoration:const InputDecoration(hintText:'Tulis pesan'))),IconButton(onPressed:send,icon:const Icon(Icons.send))]) ]));}